sp_widget.css:
.modal-content {
  border-radius: 4px;
  border: 1px solid #ddd;
  box-shadow: 0 4px 8px 0 rgba(0,0,0,0.2);
  /* This ensures the modal doesn't get too wide on larger screens */
  max-width: 500px;
  margin: 30px auto; /* Helps with centering the modal itself */
}

.modal-header {
  border-bottom: 1px solid #e5e5e5;
  padding: 15px;
  background-color: #f5f5f5;
  /* --- Change for Centering --- */
  text-align: center;
}

.modal-title {
  font-weight: bold;
  color: #333;
}

.modal-body {
  padding: 20px;
}

.hsbc-error-container {
  border: 1px solid #d9534f;
  padding: 15px;
  display: flex;
  align-items: center;
  margin-bottom: 20px;
}

.hsbc-logo img {
  max-height: 40px; /* Adjust size as needed */
  margin-right: 20px;
}

.error-title {
  font-size: 18px;
  font-weight: bold;
  color: #333;
}

.error-message-box {
  background-color: #f2dede;
  border: 1px solid #ebccd1;
  color: #a94442;
  padding: 15px;
  border-radius: 4px;
  margin-bottom: 20px;
  text-align: center;
}

.error-message-box p {
  margin: 0;
  font-weight: bold;
}

.upload-instructions h5 {
  font-weight: bold;
  margin-bottom: 10px;
}

.upload-instructions ol {
  padding-left: 20px;
}

/* --- Style for the new hyperlink --- */
.upload-instructions a {
  color: #337ab7;
  text-decoration: underline;
}

.upload-instructions a:hover {
  color: #23527c;
}


.modal-footer {
  padding: 15px;
  text-align: right;
  border-top: 1px solid #e5e5e5;
}

.btn-primary {
  background-color: #428bca;
  border-color: #357ebd;
}

.btn-default {
  background-color: #fff;
  border-color: #ccc;
  color: #333;
}

/* The CSS for the inner .close button has been removed */
